from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, n):
        self.n = n

    def __eq__(self, other):
        return self.n == other.n

    def __lt__(self, other):
        return self.n < other.n


print(sorted([Version(3), Version(1), Version(2)], key=lambda v: v.n)[0].n)
print(Version(1) <= Version(2))
